WORLD='02_World/Nusa_Sayendra.md'; RACE='04_Ras/02_Wuru Loka/Garuda.md'; CITY='03_Region/07_Nusa Sayendra/Cities & Town/Puncak Emas Swargaloka.md'; FORCE='03_Region/07_Nusa Sayendra/Faksi & Institusi/Pasukan Ksatria Sayap Garuda.md'; OATH='03_Region/07_Nusa Sayendra/Agama & Kepercayaan/Sumpah Penjaga Langit.md'; THREAT='03_Region/07_Nusa Sayendra/Threat.md'

